func (this *Indodax) ParseOrder(order any, optionalArgs ...any) any {
	//
	//     {
	//         "order_id": "12345",
	//         "submit_time": "1392228122",
	//         "price": "8000000",
	//         "type": "sell",
	//         "order_ltc": "100000000",
	//         "remain_ltc": "100000000"
	//     }
	//
	// market closed orders - note that the price is very high
	// and does not reflect actual price the order executed at
	//
	//     {
	//       "order_id": "49326856",
	//       "type": "sell",
	//       "price": "1000000000",
	//       "submit_time": "1618314671",
	//       "finish_time": "1618314671",
	//       "status": "filled",
	//       "order_xrp": "30.45000000",
	//       "remain_xrp": "0.00000000"
	//     }
	//
	// cancelOrder
	//
	//    {
	//        "order_id": 666883,
	//        "client_order_id": "clientx-sj82ks82j",
	//        "type": "sell",
	//        "pair": "btc_idr",
	//        "balance": {
	//            "idr": "33605800",
	//            "btc": "0.00000000",
	//            ...
	//            "frozen_idr": "0",
	//            "frozen_btc": "0.00000000",
	//            ...
	//        }
	//    }
	//
	market := GetArg(optionalArgs, 0, nil)
	_ = market
	var side any = nil
	if IsTrue(InOp(order, "type")) {
		side = GetValue(order, "type")
	}
	var status any = this.ParseOrderStatus(this.SafeString(order, "status", "open"))
	var symbol any = nil
	var cost any = nil
	var price any = this.SafeString(order, "price")
	var amount any = nil
	var remaining any = nil
	var filled any = nil
	var marketId any = this.SafeString(order, "pair")
	market = this.SafeMarket(marketId, market)
	if IsTrue(!IsEqual(market, nil)) {
		symbol = GetValue(market, "symbol")
		var quoteId any = GetValue(market, "quoteId")
		var baseId any = GetValue(market, "baseId")
		if IsTrue(IsTrue((IsEqual(GetValue(market, "quoteId"), "idr"))) && IsTrue((InOp(order, "order_rp")))) {
			quoteId = "rp"
		}
		if IsTrue(IsTrue((IsEqual(GetValue(market, "baseId"), "idr"))) && IsTrue((InOp(order, "remain_rp")))) {
			baseId = "rp"
		}
		cost = this.SafeString(order, Add("order_", quoteId))
		amount = this.SafeString(order, Add("order_", baseId))
		remaining = this.SafeString(order, Add("remain_", baseId))
		// filled buy orders on idr-quoted markets carry the executed base amount
		// only in a dynamic receive_{base} field, https://github.com/ccxt/ccxt/issues/26413
		filled = this.SafeString(order, Add("receive_", baseId))
	}
	var timestamp any = this.SafeInteger(order, "submit_time")
	var fee any = nil
	var id any = this.SafeString(order, "order_id")
	return this.SafeOrder(map[string]any{
		"info":               order,
		"id":                 id,
		"clientOrderId":      this.SafeString(order, "client_order_id"),
		"timestamp":          timestamp,
		"datetime":           this.Iso8601(timestamp),
		"lastTradeTimestamp": nil,
		"symbol":             symbol,
		"type":               "limit",
		"timeInForce":        nil,
		"postOnly":           nil,
		"side":               side,
		"price":              price,
		"triggerPrice":       nil,
		"cost":               cost,
		"average":            nil,
		"amount":             amount,
		"filled":             filled,
		"remaining":          remaining,
		"status":             status,
		"fee":                fee,
		"trades":             nil,
	})
}

